pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 depositAmount, bool shouldFail) public {
        // Bound deposit to a reasonable non-zero range to avoid overflow or zero-value calls
        depositAmount = bound(depositAmount, 1, 100 ether);

        // Deploy an adversarial callee that reverts when receiving Ether if shouldFail is true,
        // or that accepts Ether normally if shouldFail is false.
        // The fuzzer will explore both behaviours.
        ReverterOrAcceptor helper = new ReverterOrAcceptor(shouldFail);

        // Fund the helper as the caller (simulate some user that will withdraw through this helper)
        vm.deal(address(helper), depositAmount);

        // First, the helper gives Ether to c to set its balance in c
        vm.prank(address(helper));
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        // Record balance before withdrawal
        uint256 balanceBefore = c.balances(address(helper));

        // The helper calls withdraw on c. If shouldFail=true, the helper's receive reverts,
        // causing the low-level call inside withdraw() to fail.
        vm.prank(address(helper));
        helper.callWithdraw(address(c));

        // After withdraw, the caller's balance is observed.
        uint256 balanceAfter = c.balances(address(helper));

        // If the withdrawal call failed (shouldFail=true), the reference contract's require would
        // have reverted the whole transaction, leaving the balance unchanged.
        // The buggy version skips the require, always setting balances[msg.sender]=0.
        // Therefore, when shouldFail, the reference preserves balance, but the mutant zeroes it.
        // Our assertion: if the call should fail, the balance must remain unchanged.
        // If the call should succeed, any outcome is fine.
        assertTrue(!shouldFail || balanceAfter == balanceBefore);
    }
}

// Minimal adversarial callee that either reverts on receive or accepts Ether,
// depending on a flag set at construction.
contract ReverterOrAcceptor {
    bool immutable revertOnReceive;
    constructor(bool _revertOnReceive) {
        revertOnReceive = _revertOnReceive;
    }
    fallback() external payable {
        if (revertOnReceive) {
            revert("adversarial revert");
        }
    }
    function callWithdraw(address target) external {
        // This calls withdraw on C as msg.sender = address(this).
        // If this contract's receive reverts, the internal low-level call in withdraw() will return false.
        C(target).withdraw();
    }
}

