pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount, uint256 seed) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(0) && actor != address(c));
        // Deploy a helper that always reverts on receiving Ether
        Reverter reverter = new Reverter();
        address caller = reverter.actor(); // reverter uses its own address as the actor
        vm.deal(caller, amount);
        // Deposit Ether into C using the reverter as msg.sender
        vm.prank(caller);
        (bool success,) = address(c).call{value: amount}("");
        require(success, "deposit failed");
        // Record balance before withdraw
        uint256 balanceBefore = c.balances(caller);
        assertEq(balanceBefore, amount, "balance should equal deposited amount");
        // Attempt withdraw – the reverter's fallback will revert, causing the low-level call in withdraw to fail
        vm.prank(caller);
        try c.withdraw() {
            // If withdraw does not revert, the reference must have zeroed the balance
            assertEq(c.balances(caller), 0, "balance must be zero after successful withdraw");
        } catch {
            // If withdraw reverts, the reference preserves the balance; buggy version would have zeroed it before
            // the reversion propagates, but the state change (balances zeroed) would remain because
            // the buggy version does not require the success of the call and always zeroes the balance.
            // However, in the buggy version the require is removed, so withdraw does NOT revert even if the call fails.
            // Therefore, the catch block only triggers on the reference (or if the assertion above fails?).
            // Actually, the buggy withdraw never reverts due to failed call, so catch won't execute there.
            // To capture the difference: in buggy, withdraw succeeds (no revert) and balance becomes 0.
            // In reference, withdraw reverts and balance remains amount.
            // So after the try/catch we check the actual balance.
            assertEq(c.balances(caller), amount, "after revert, balance must remain unchanged (reference behavior)");
        }
        // The single assertion that distinguishes: after the operation, the balance of caller must be 0 or amount,
        // but we need a general rule. Better: balance after must be 0 if and only if the call succeeded.
        // But we can assert that if withdraw did not revert, balance == 0; if it reverted, balance == amount.
        // The bug violates this: in buggy, withdraw never reverts on failed call and balance becomes 0.
        // So the rule: either balance is 0 and withdraw did not revert, or balance is amount and withdraw reverted.
        // We'll simplify: after any attempt, the balance is exactly what remains.
        // Actually, the invariant: for a caller with balance > 0, after withdraw(), the balance is either unchanged (if call failed) or 0 (if call succeeded).
        // The bug always sets it to 0, so the balance can be 0 even when the call failed.
        // We can assert: if the reverter's balance before is amount, then after withdraw, either the contract reverted or balance is 0.
        // But the reference reverts, so balance remains amount. The bug doesn't revert and balance is 0.
        // So the property: after the call (revert or not), the sum of balances across all addresses is unchanged? No.
        // Let's just check the final balance against the expected value based on whether the external call succeeded.
        // Since we know the reverter always reverts, the call will fail. Therefore, the correct behavior is that balance remains amount.
        // The bug sets it to 0. So the assertion: final balance of caller == amount (because we know the call will fail).
        // But we need a single assertion that holds for all inputs. We can't assume the external call fails for all addresses;
        // but we specifically deployed a Reverter that always reverts, so the external call to it WILL fail for sure.
        // That's allowed: deploying an adversarial helper ensures the external call fails, so we can assert on that.
        // The fuzzer varies actor and amount, but the interaction is with the Reverter, which always reverts.
        // So the general rule: "if withdraw is called by an address that always reverts on receiving Ether, the balance of that address remains unchanged." 
        // The bug zeroes the balance regardless.
        assertEq(c.balances(caller), amount, "balance must remain unchanged when external call fails");
    }
}

contract Reverter {
    fallback() external payable {
        revert("Revert on receive");
    }
    function actor() external view returns (address) {
        return address(this);
    }
}

