pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
    }

    function testFuzz_property(uint256 amount, uint256 attackDepth) public {
        amount = bound(amount, 1, 100 ether);
        attackDepth = bound(attackDepth, 1, 5);

        // Deploy a re-entrant attacker that will call withdraw again during the first withdraw.
        Attacker attacker = new Attacker(c, attackDepth);

        // Fund the contract C with attacker's address
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        (bool funded, ) = address(c).call{value: amount}("");
        require(funded, "funding failed");

        // Record the attacker's balance before the attack
        uint256 balanceBefore = c.balances(address(attacker));

        // Attack: attacker calls withdraw, which sends ether back to attacker, which re-enters withdraw again.
        // The inner calls will succeed and drain balance; the outer most call's send will fail because C runs out of ether.
        vm.prank(address(attacker));
        attacker.attack();

        // After everything settles, check the final balance.
        // Correct behavior: the outer withdraw should revert entirely because the call to attacker fails,
        // preserving the state from before the attack (balance unchanged).
        // Buggy behavior: the lock is missing, so re-entrancy succeeds partially and the last step sets balance to 0.
        uint256 balanceAfter = c.balances(address(attacker));
        assertEq(balanceAfter, balanceBefore);
    }
}

contract Attacker {
    C public target;
    uint256 public depth;
    uint256 public maxDepth;

    constructor(C _target, uint256 _maxDepth) {
        target = _target;
        maxDepth = _maxDepth;
        depth = 0;
    }

    function attack() external {
        depth = 0;
        target.withdraw();
    }

    receive() external payable {
        if (depth < maxDepth) {
            depth++;
            // Re-enter withdraw while we still have balance recorded
            target.withdraw();
        }
        // After re-entrancy finishes, control returns to the original withdraw.
        // The original withdraw will then send ether to this contract again, but if balance is drained,
        // the low-level call will fail, triggering revert in the correct version, discarding balance = 0 assignment.
        // In the buggy version, no lock prevents re-entrancy; the failing call still sets balances[msg.sender] = 0 after re-entry.
    }
}

