pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initialDeposit, uint256 reentryTimes) public {
        // keep values in admissible range (small enough to avoid overflow and deep recursion)
        initialDeposit = bound(initialDeposit, 1, 1 ether);
        reentryTimes = bound(reentryTimes, 1, 5);

        // deploy an attacker that re-enters withdraw() a fixed number of times,
        // collecting the total ETH received during the entire call chain
        ReentrantAttacker attacker = new ReentrantAttacker(c, reentryTimes);

        // fund the attacker so it can deposit into C
        vm.deal(address(attacker), initialDeposit * 2);

        // attacker deposits initialDeposit into C via its fallback (triggered by a call with value)
        vm.prank(address(attacker));
        (bool ok,) = address(c).call{value: initialDeposit}("");
        require(ok, "deposit failed");

        // the attacker now initiates a single withdraw(); the receive() callback
        // will re-enter withdraw() reentryTimes more times before the first one finishes.
        uint256 attackerBalanceBefore = address(attacker).balance;
        vm.prank(address(attacker));
        attacker.attack();
        uint256 attackerBalanceAfter = address(attacker).balance;

        // General invariant: the total ETH received by the attacker across all the
        // re-entrant calls must NOT exceed its original deposit in C. In the correct
        // contract the lock prevents reentrancy, so only one withdraw() succeeds,
        // sending exactly initialDeposit. In the buggy mutant, consecutive re-entrant
        // calls drain more than initialDeposit, violating this bound.
        assertTrue(attackerBalanceAfter - attackerBalanceBefore <= initialDeposit);
    }
}

contract ReentrantAttacker {
    C target;
    uint256 remaining;

    constructor(C _target, uint256 _reenterCount) {
        target = _target;
        remaining = _reenterCount;
    }

    // called by InvMutTest to start the attack
    function attack() external {
        target.withdraw();
    }

    receive() external payable {
        if (remaining > 0) {
            remaining--;
            target.withdraw();
        }
    }
}

